function readout() { return JSON.parse(_readout) }
function cards()   { return JSON.parse(_cards) }
function header()  { return JSON.parse(_header) }
function detail()  { return JSON.parse(_detail) }
function source()  { return JSON.parse(_source) }

// The whole read surface, as the body receives it: source + its cards, headerInfo and (optionally) an
// open detail. reviewing = true leaves the review badge on (the session as captured).
function session(withDetail) {
    const s = source()
    s.cards = cards()
    s.headerInfo = header()
    if (withDetail) {
        const d = detail()
        s.detail = d
        s.detailConditionId = d.id
    }
    return s
}

// ═══════════════════════════ the live states, cut from the real session ═══════════════════════════
// The model publishes each of these; a test cannot make a session produce them on demand, so they are
// SYNTHESISED from the real one exactly as the register round's harness did ($D/reg/LiveStates.qml,
// INVENTORY §3): the session cut to its first n shots, the newest picked or nothing picked, the stage
// and tense set, the review badge cleared for a live session. Each returns { source, readout } where
// source carries headerInfo and cards (what the body reads) and readout is shotReadout() or null.
// The one liberty taken: a condition's state on the cut shot is taken from its own tick at that shot
// (the real readout is shot 8's), so the strips, the dots and the after-shot delta agree.

function _rec(ticks) {
    const m = ticks.filter(t => t.state === "fired" || t.state === "clean").length
    const f = ticks.filter(t => t.state === "fired").length
    return f + " of " + m + " measurable shots"
}
function _fig(v) { const m = String(v || "").match(/^\s*([−\-+]?\d[\d.,]*)/); return m ? m[1] : "-" }
function plainId(j) { return j + 1 }
// a 23-shot session's ids: swing id 6 was deleted, so ids run 1–5, 7–24 (ordinals are not ids)
function deletedSixId(j) { return j < 5 ? j + 1 : j + 2 }

// the first n ticks (repeating 1–15 past 15), relabelled with ids, the pick marked
function cut(ticks, n, idOf, pick) {
    const out = []
    for (let j = 0; j < n; ++j) {
        const t = ticks[j % ticks.length] || { state: "clean" }
        out.push({ state: t.state, shotId: idOf(j), selected: j === pick })
    }
    return out
}
// a condition as it read on shot i: its state from its own tick there
function _restate(c, state) {
    const o = Object.assign({}, c)
    if (state === "fired") {
        o.stateKind = "fired"; o.state = "OUT"; o.strengthKnown = true
        o.strengthExcess = c.stateKind === "fired" ? c.strengthExcess : 2.3
    } else if (state === "clean") {
        o.stateKind = "clean"; o.state = "IN"; o.strengthKnown = true
        o.strengthExcess = c.stateKind === "clean" ? c.strengthExcess : 1.2
    } else {
        o.stateKind = "notAssessable"; o.state = "—"; o.strengthKnown = false
        o.valueText = "not measurable"; o.reason = c.reason || "metric not produced"
    }
    return o
}
function readoutAt(r0, i, n, idOf) {
    const r = Object.assign({}, r0)
    r.shotIndex = i; r.shotCount = n; r.shotId = idOf(i)
    r.conditions = (r0.conditions || []).map(c => {
        const t = cut(c.ticks || [], n, idOf, i)
        const o = _restate(c, t[i] ? t[i].state : "notAssessable")
        o.ticks = t; o.recurrence = _rec(t); o.firingsAfterText = ""; o.selectedIndex = i
        return o
    })
    const cs = r.conditions
    r.firedCount = cs.filter(c => c.stateKind === "fired").length
    r.cleanCount = cs.filter(c => c.stateKind === "clean").length
    r.notAssessableCount = cs.filter(c => c.stateKind === "notAssessable").length
    r.measurableSetCount = r.firedCount + r.cleanCount
    const pats = cs.filter(c => c.stateKind === "fired" && c.tierTag === "pattern").length
    r.headline = r.firedCount + " of " + r.measurableSetCount + " conditions fired on this swing · " + pats + " of them patterns"
    r.note = r.notAssessableCount ? r.notAssessableCount + " measures not assessable on this capture" : ""
    return r
}
// a card re-pointed at shot i of a session cut to n shots
function cardAt(c, i, n, idOf, live) {
    const t = cut(c.ticks || [], n, idOf, i)
    const run = (c.spread && c.spread.run) || []
    const rr = []
    for (let j = 0; j < n; ++j) {
        const q = run[j % run.length]
        if (q) rr.push(Object.assign({}, q, { index: j, shotId: idOf(j), current: j === i, selected: j === i }))
    }
    const cur = rr[i]
    const sp = Object.assign({}, c.spread || {}, {
        run: rr, currentNumber: cur && cur.assessable ? _fig(cur.valueText) : "-",
        currentReadout: cur ? String(cur.readout || "").replace(/^shot \d+/, "shot " + (i + 1)) : "" })
    const o = Object.assign({}, c, { ticks: t, recurrence: _rec(t), spread: sp,
                                     thisShot: t[i] ? t[i].state : "notAssessable",
                                     valueText: cur && cur.assessable ? cur.valueText : "not measurable" })
    if (live) o.firingsAfterText = ""
    return o
}
function chip(c) {
    return { id: c.id, name: c.name, kind: "fired", tier: c.tierTag === "pattern" ? "pattern" : "watching",
             strength: c.strength, strengthExcess: c.strengthExcess, strengthKnown: c.strengthKnown,
             strengthText: c.strengthText, focus: false }
}
function deltaOf(r, surfaced) {
    const cs = r.conditions || []
    const fired = cs.filter(c => c.stateKind === "fired"), clean = cs.filter(c => c.stateKind === "clean")
    const na = cs.filter(c => c.stateKind === "notAssessable"), pats = fired.filter(c => c.tierTag === "pattern").length
    return { shotId: r.shotId, shotIndex: r.shotIndex, firedCount: fired.length, cleanCount: clean.length,
             notAssessableCount: na.length, firedPatternCount: pats, fired: fired.map(chip), newPatterns: [],
             streakBroken: false, surfaced: surfaced,
             headline: fired.length + " of " + (fired.length + clean.length) + " conditions fired on this swing · "
                       + pats + " of them " + (pats === 1 ? "pattern" : "patterns"),
             note: na.length ? na.length + (na.length === 1 ? " measure" : " measures") + " not assessable on this capture" : "" }
}
function thisShotOf(r) {
    const d = deltaOf(r, true)
    const out = (r.conditions || []).filter(c => c.stateKind === "fired").map(chip)
    if (d.notAssessableCount) out.push({ kind: "notAssessable", name: d.notAssessableCount + " not assessable on this capture" })
    return out
}
function watchingOf(r, cs) {
    const pats = {}
    for (const c of cs) pats[c.id] = true
    return (r.conditions || []).filter(c => !pats[c.id] && (c.ticks || []).some(t => t.state === "fired"))
                               .map(c => ({ id: c.id, name: c.name, recurrence: c.recurrence }))
}
function liveHeader(h, over) {
    return Object.assign({}, h || {}, { reviewBadge: "", reviewNote: "", reviewing: false, closed: false, closingLine: "",
                                        reviewFootLine: "", cadenceNote: "", coldLine: "" }, over || {})
}
// a LIVE session cut to its first n shots, the newest picked (picked) or nothing picked
function liveSession(n, stage, picked, opts) {
    opts = opts || {}
    const r0 = readout(), c0 = cards(), s = source(), h = header()
    const i = n - 1
    const r = readoutAt(r0, i, n, plainId)
    if (opts.noCards) r.conditions = r.conditions.map(c => c.tierTag === "pattern" ? Object.assign({}, c, { tierTag: "watching" }) : c)
    const cs = opts.noCards ? [] : c0.map(c => cardAt(c, i, n, plainId, true))
    for (const k of (opts.fresh || [])) if (cs[k]) cs[k].fresh = true
    Object.assign(s, { stage: stage, closed: false, reviewing: false, shotCount: n, patternCount: cs.length, cards: cs,
                       watching: watchingOf(r, cs), bookends: [], afterShotDelta: deltaOf(r, true), thisShot: thisShotOf(r),
                       quiet: false, selectedShotId: picked ? r.shotId : -1, expectations: opts.expectations || [],
                       declaredMiss: "", declaredMissName: "", focusConditionId: "", detailConditionId: "", detail: null })
    s.headerInfo = liveHeader(h, { stage: stage, stageLabel: stage.toUpperCase(), shotCount: n, patternCount: cs.length,
                                   countLine: cs.length + (cs.length === 1 ? " pattern" : " patterns") + " · counted over all " + n
                                              + (n === 1 ? " shot" : " shots"),
                                   shotLabel: "shot " + n, reachedEstablished: stage === "established" })
    return { source: s, readout: picked ? r : null, newest: r }
}

// ── the states (INVENTORY §1 numbers) ──
// S1: no source at all
function noSource() { return { source: null, readout: null } }
// S2: live, Cold, no shots
function cold0() {
    const s = source()
    Object.assign(s, { stage: "cold", closed: false, reviewing: false, shotCount: 0, patternCount: 0, cards: [], watching: [],
                       bookends: [], afterShotDelta: ({}), thisShot: [], quiet: false, selectedShotId: -1, expectations: [],
                       declaredMiss: "", declaredMissName: "", focusConditionId: "", detailConditionId: "", detail: null })
    s.headerInfo = liveHeader(header(), { stage: "cold", stageLabel: "COLD", shotCount: 0, patternCount: 0,
                                          coldLine: "Too few swings to call a pattern.",
                                          countLine: "0 patterns · counted over all 0 shots", shotLabel: "no shots yet",
                                          reachedEstablished: false })
    return { source: s, readout: null }
}
// S3/S4: Cold with two shots, and the fault profile's expectations (or none)
var expectationRows = [
    { id: "over_the_top", name: "Over the top", text: "pattern in 9 of your last 10 sessions", caveat: "an expectation to test, not a finding" },
    { id: "early_extension", name: "Early extension", text: "pattern in 7 of your last 10 sessions", caveat: "an expectation to test, not a finding" },
    { id: "hanging_back", name: "Hanging back", text: "pattern in 4 of your last 9 sessions", caveat: "an expectation to test, not a finding" }]
function cold2(withProfile) {
    const o = liveSession(2, "cold", true, { noCards: true, expectations: withProfile === false ? [] : JSON.parse(JSON.stringify(expectationRows)) })
    o.source.headerInfo.coldLine = "Too few swings to call a pattern."
    o.source.headerInfo.reachedEstablished = false
    return o
}
// S5 / S6
function forming() { return liveSession(6, "forming", true, { fresh: [2, 5] }) }
function established() { return liveSession(12, "established", true) }
// S10: live, shots exist, nothing picked (D3: This shot reads the newest swing)
function liveNoPick() { return liveSession(15, "established", false) }
// S8: the newest swing held back by the bandwidth cadence (synthetic: its pattern firings cleared)
function quiet(picked) {
    const o = liveSession(15, "established", true)
    const r = Object.assign({}, o.readout)
    r.conditions = r.conditions.map(c => c.stateKind === "fired" && c.tierTag === "pattern"
        ? Object.assign({}, c, { stateKind: "clean", state: "IN", strengthExcess: 1.2,
                                 ticks: c.ticks.map((t, j) => j === 14 ? Object.assign({}, t, { state: "clean" }) : t) }) : c)
    const cs = o.source.cards.map(c => c.thisShot === "fired"
        ? Object.assign({}, c, { thisShot: "clean", ticks: c.ticks.map((t, j) => j === 14 ? Object.assign({}, t, { state: "clean" }) : t) }) : c)
    o.source.cards = cs
    o.source.quiet = true
    o.source.afterShotDelta = deltaOf(r, false)
    o.source.thisShot = thisShotOf(r)
    o.source.headerInfo.cadenceNote = "BANDWIDTH · QUIET"
    o.readout = picked === false ? null : r
    return o
}
// S11: live, an OLDER swing picked (shot 8 of 15 while the session runs on)
function liveOlderPick() {
    const s = session(false)
    s.cards = s.cards.map(c => Object.assign({}, c, { firingsAfterText: "" }))
    Object.assign(s, { stage: "established", closed: false, reviewing: false, bookends: [] })
    s.headerInfo = liveHeader(s.headerInfo, { stage: "established", stageLabel: "ESTABLISHED", shotLabel: "shot 15" })
    const r = readout()
    r.conditions = r.conditions.map(c => Object.assign({}, c, { firingsAfterText: "" }))
    return { source: s, readout: r }
}
// S13: the live session has ended, nothing picked
function closing() {
    const s = session(false)
    Object.assign(s, { stage: "closing", closed: true, reviewing: false, selectedShotId: -1 })
    s.headerInfo = liveHeader(s.headerInfo, { stage: "closing", stageLabel: "CLOSING", closed: true, shotLabel: "shot 15" })
    return { source: s, readout: null }
}
// S15 / S16: review, nothing picked / shot 8 picked (the session as captured)
function reviewNoPick() { const s = session(false); s.selectedShotId = -1; return { source: s, readout: null } }
function reviewed(withDetail) { return { source: session(withDetail === true), readout: readout() } }
// S38: nothing fired on the picked shot
function zeroFired() {
    const r0 = readout(), s = session(false)
    const r = Object.assign({}, r0)
    r.conditions = r0.conditions.map(c => c.stateKind === "fired"
        ? Object.assign({}, c, { stateKind: "clean", state: "IN", strengthExcess: 1.2,
                                 ticks: c.ticks.map((t, j) => j === r0.shotIndex ? Object.assign({}, t, { state: "clean" }) : t) }) : c)
    r.firedCount = 0; r.cleanCount = r.conditions.filter(c => c.stateKind === "clean").length
    r.measurableSetCount = r.cleanCount
    s.cards = s.cards.map(c => c.thisShot === "fired" ? Object.assign({}, c, { thisShot: "clean" }) : c)
    return { source: s, readout: r }
}
// S40: 23 shots, swing id 6 deleted, reviewed at the 8th (id 9)
function long23() {
    const r0 = readout(), c0 = cards(), s = session(false)
    const n = 23, i = r0.shotIndex, idOf = deletedSixId
    const r = Object.assign({}, r0, { shotCount: n, shotIndex: i, shotId: idOf(i),
        conditions: r0.conditions.map(c => { const t = cut(c.ticks || [], n, idOf, i); return Object.assign({}, c, { ticks: t, recurrence: _rec(t) }) }) })
    const cs = c0.map(c => cardAt(c, i, n, idOf, false))
    const bk = (s.bookends || []).map(b => Object.assign({}, b, { representativeShotId: idOf(b.representativeShotId - 1),
                                                                  worstShotId: idOf(b.worstShotId - 1), bestShotId: idOf(b.bestShotId - 1) }))
    const ws = (s.watching || []).map(w => { const c = r.conditions.find(x => x.id === w.id); return c ? Object.assign({}, w, { recurrence: c.recurrence }) : w })
    Object.assign(s, { shotCount: n, cards: cs, bookends: bk, watching: ws, selectedShotId: idOf(i) })
    s.headerInfo = Object.assign({}, s.headerInfo, { shotCount: n, reviewBadge: "REVIEWING · shot " + (i + 1) + " of " + n,
                                                     countLine: cs.length + " patterns · counted over all " + n + " shots",
                                                     shotLabel: "shot " + (i + 1) + " of " + n })
    return { source: s, readout: r }
}
